/* ---------- backgrounds (640 x 400), objects react to data-* state on #bg ---------- */
function leds(x, y, w, h, n, seed){ let o = ''; for (let i = 0; i < n; i++){ const r = Math.abs(Math.sin(seed + i * 12.9898) * 43758.5453) % 1, r2 = Math.abs(Math.sin(seed + i * 78.233) * 12345.678) % 1; o += `<rect class="led" x="${(x + r * w).toFixed(1)}" y="${(y + r2 * h).toFixed(1)}" width="4" height="2.4" fill="${r > .8 ? '#ff5a4a' : r > .4 ? '#5aff9a' : '#ffc94a'}" style="animation-delay:${(-r2 * 3).toFixed(2)}s;animation-duration:${(0.6 + r * 2).toFixed(2)}s"/>`; } return o; }
function rack(x, y, w, h, seed){ let o = `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#141a24" stroke="#2a3446" stroke-width="2"/>`; for (let i = 0; i < Math.floor(h / 26); i++) o += `<rect x="${x + 5}" y="${y + 6 + i * 26}" width="${w - 10}" height="20" rx="2" fill="#1d2634" stroke="#0c1018"/>` + leds(x + 9, y + 10 + i * 26, w - 24, 10, 4, seed + i); return o; }
function miniChar(id, x, y, s, flip){ return `<g transform="translate(${x} ${y}) scale(${s})"><g class="ch mini" data-id="${id}">${charSVG(id, flip)}</g></g>`; }
